"use client";

import React, { useState, useMemo, useRef } from "react";
import { 
  FileText, ShieldCheck, Share2, PenTool, Users, Lock, 
  Download, Trash2, Eye, Plus, History, AlertTriangle, 
  CheckCircle2, Printer, Search, X, FilePlus, Fingerprint,
  ChevronRight, Calendar, briefcase
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";

/* ==========================================================================
   1. THE ARCHITECTURE (TYPES & LOGIC)
   ========================================================================== */

type DocStatus = "Verified" | "Action Required" | "Expiring" | "Signed" | "Pending";
type DocCategory = "Identity" | "Finance" | "Family" | "Corporate" | "Medical";

interface Document {
  id: string;
  name: string;
  category: DocCategory;
  status: DocStatus;
  size: string;
  uploadedAt: string;
  expiryDate?: string;
  version: string;
  isSensitive: boolean;
  auditTrail: { action: string; user: string; time: string }[];
}

const INITIAL_DATA: Document[] = [
  {
    id: "doc_1",
    name: "Passport_Primary_Rahul.pdf",
    category: "Identity",
    status: "Expiring",
    size: "3.2 MB",
    uploadedAt: "12 Jan 2026",
    expiryDate: "2026-03-12",
    version: "v1.0",
    isSensitive: true,
    auditTrail: [{ action: "Uploaded", user: "Rahul Sharma", time: "12 Jan, 10:00 AM" }]
  },
  {
    id: "doc_2",
    name: "FY25_Tax_Declaration.pdf",
    category: "Finance",
    status: "Verified",
    size: "1.1 MB",
    uploadedAt: "05 Jan 2026",
    version: "v2.1",
    isSensitive: true,
    auditTrail: [
        { action: "Uploaded", user: "Rahul Sharma", time: "05 Jan, 02:00 PM" },
        { action: "Verified", user: "Finance Dept", time: "06 Jan, 11:30 AM" }
    ]
  }
];

export default function UltimateDocumentHub() {
  const [docs, setDocs] = useState<Document[]>(INITIAL_DATA);
  const [activeTab, setActiveTab] = useState<string>("All");
  const [search, setSearch] = useState("");
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [showRequestModal, setShowRequestModal] = useState(false);

  // --- Search & Filter Logic ---
  const filteredDocs = useMemo(() => {
    return docs.filter(d => {
      const matchesSearch = d.name.toLowerCase().includes(search.toLowerCase());
      const matchesTab = activeTab === "All" || d.category === activeTab;
      return matchesSearch && matchesTab;
    });
  }, [docs, activeTab, search]);

  // --- Handlers ---
  const handleDelete = (id: string) => {
    if (confirm("Delete this document? This action is logged.")) {
      setDocs(docs.filter(d => d.id !== id));
      setSelectedDoc(null);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8F9FB] dark:bg-[#050505] text-gray-900 dark:text-gray-100 flex flex-col">
      
      {/* 2. THE TOP COMMAND STRIP */}
      <div className="p-6 lg:px-10 flex flex-col md:flex-row justify-between items-center gap-4 bg-white dark:bg-[#0A0A0A] border-b dark:border-white/5">
        <div className="flex items-center gap-4">
          <div className="bg-brand-600 p-3 rounded-2xl shadow-xl shadow-brand-500/20">
            <Fingerprint className="text-white w-6 h-6" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight uppercase">Identity Vault</h1>
            <p className="text-[10px] font-bold text-gray-400 tracking-widest">SECURE OPERATIONAL DATA STORE</p>
          </div>
        </div>

        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-80">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500 w-4 h-4" />
            <input 
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by file name or category..." 
              className="w-full bg-gray-50 dark:bg-white/5 border-none rounded-2xl py-3 pl-12 pr-4 text-xs font-bold focus:ring-2 focus:ring-brand-500"
            />
          </div>
          <button 
            onClick={() => setShowRequestModal(true)}
            className="p-3 bg-gray-100 dark:bg-white/5 rounded-2xl hover:bg-brand-50 hover:text-brand-600 transition-all shadow-sm"
            title="Request Official Letter"
          >
            <Printer size={20} />
          </button>
          <button 
            onClick={() => setShowUploadModal(true)}
            className="bg-brand-600 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-black transition-all flex items-center gap-2"
          >
            <Plus size={18} /> Upload
          </button>
        </div>
      </div>

      {/* 3. THE CORE WORKSPACE */}
      <div className="flex-1 flex overflow-hidden">
        
        {/* Left Side: Navigation & List */}
        <div className="flex-1 flex flex-col p-6 lg:p-10 space-y-6 overflow-y-auto">
          
          {/* Category Tabs */}
          <div className="flex gap-2 overflow-x-auto no-scrollbar">
            {["All", "Identity", "Finance", "Family", "Corporate", "Medical"].map(cat => (
              <button 
                key={cat}
                onClick={() => setActiveTab(cat)}
                className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                  activeTab === cat ? "bg-gray-900 text-white dark:bg-brand-600" : "text-gray-400 hover:text-gray-900 dark:hover:text-white"
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Document Table */}
          <div className="bg-white dark:bg-[#0A0A0A] rounded-[2.5rem] border border-gray-100 dark:border-white/5 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-50/50 dark:bg-white/5 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400 border-b dark:border-white/5">
                <tr>
                  <th className="px-8 py-5">Managed Document</th>
                  <th className="px-8 py-5">Life Cycle</th>
                  <th className="px-8 py-5">Security</th>
                  <th className="px-8 py-5 text-right">Ops</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50 dark:divide-white/5">
                {filteredDocs.map(doc => (
                  <tr 
                    key={doc.id} 
                    onClick={() => setSelectedDoc(doc)}
                    className={`group cursor-pointer transition-all ${selectedDoc?.id === doc.id ? "bg-brand-50/50 dark:bg-brand-600/10" : "hover:bg-gray-50/50 dark:hover:bg-white/[0.02]"}`}
                  >
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
                        <div className={`p-3 rounded-2xl ${selectedDoc?.id === doc.id ? "bg-brand-600 text-white" : "bg-gray-100 dark:bg-white/5 text-gray-400"}`}>
                          <FileText size={20} />
                        </div>
                        <div>
                          <p className="text-sm font-black tracking-tight">{doc.name}</p>
                          <p className="text-[10px] font-bold text-gray-400 uppercase mt-0.5">{doc.category} • {doc.size}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                       <StatusBadge status={doc.status} />
                       {doc.expiryDate && <p className="text-[9px] font-bold text-red-500 mt-1 uppercase">Exp: {doc.expiryDate}</p>}
                    </td>
                    <td className="px-8 py-6">
                       <div className="flex items-center gap-2">
                         {doc.isSensitive ? <Lock size={12} className="text-brand-600" /> : <ShieldCheck size={12} className="text-gray-400" />}
                         <span className="text-[10px] font-black uppercase tracking-tighter">{doc.isSensitive ? "High Sensitivity" : "Standard"}</span>
                       </div>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                         <button className="p-2 hover:bg-white dark:hover:bg-white/10 rounded-xl transition-all"><Eye size={18}/></button>
                         <button className="p-2 hover:bg-white dark:hover:bg-white/10 rounded-xl transition-all"><Share2 size={18}/></button>
                         <button onClick={(e) => { e.stopPropagation(); handleDelete(doc.id); }} className="p-2 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Right Side: THE INTELLIGENCE PANEL (Deep Context) */}
        <div className="hidden lg:flex w-96 border-l dark:border-white/5 bg-white dark:bg-[#0A0A0A] p-8 flex-col gap-8 shadow-2xl">
           {!selectedDoc ? (
             <div className="h-full flex flex-col items-center justify-center text-center opacity-40 grayscale">
                <ShieldCheck size={64} className="mb-4 text-gray-300" />
                <p className="text-xs font-black uppercase tracking-widest text-gray-400 leading-relaxed">Select a secure asset <br /> to audit details</p>
             </div>
           ) : (
             <div className="animate-in fade-in slide-in-from-right-4 duration-300">
                <div className="flex justify-between items-start mb-8">
                  <h3 className="text-xl font-black tracking-tighter uppercase">Audit Trail</h3>
                  <Badge size="sm" color="brand">{selectedDoc.version}</Badge>
                </div>

                <div className="space-y-8">
                  {/* Activity History */}
                  <div className="space-y-6">
                    {selectedDoc.auditTrail.map((log, i) => (
                      <div key={i} className="flex gap-4 relative">
                        <div className="flex flex-col items-center">
                           <div className="w-3 h-3 rounded-full bg-brand-500 border-4 border-white dark:border-gray-900 z-10" />
                           <div className="w-[1px] h-full bg-gray-100 dark:bg-white/10 absolute top-3" />
                        </div>
                        <div>
                           <p className="text-xs font-black">{log.action}</p>
                           <p className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter mt-1">{log.user} • {log.time}</p>
                        </div>
                      </div>
                    ))}
                  </div>

                  {/* Operational Actions */}
                  <div className="pt-8 border-t dark:border-white/5 space-y-3">
                    <button className="w-full flex items-center justify-between p-4 bg-gray-50 dark:bg-white/5 rounded-2xl hover:bg-brand-500 hover:text-white transition-all group">
                       <span className="text-[10px] font-black uppercase tracking-widest">Digital Signature</span>
                       <PenTool size={16} className="opacity-40 group-hover:opacity-100" />
                    </button>
                    <button className="w-full flex items-center justify-between p-4 bg-gray-50 dark:bg-white/5 rounded-2xl hover:bg-brand-500 hover:text-white transition-all group">
                       <span className="text-[10px] font-black uppercase tracking-widest">Share External Link</span>
                       <Share2 size={16} className="opacity-40 group-hover:opacity-100" />
                    </button>
                  </div>

                  <div className="p-6 bg-red-50 dark:bg-red-500/10 rounded-[2rem] border border-red-100 dark:border-red-500/20">
                    <div className="flex items-center gap-2 mb-2 text-red-600">
                      <AlertTriangle size={16} />
                      <p className="text-[10px] font-black uppercase">Sensitivity Alert</p>
                    </div>
                    <p className="text-[10px] text-red-500/80 font-medium leading-relaxed">This document contains PII (Personally Identifiable Information). Access is restricted to HRBP and Department leads.</p>
                  </div>
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
}

/* --- REUSABLE MICRO-COMPONENTS --- */

const StatusBadge = ({ status }: { status: DocStatus }) => {
  const styles: any = {
    Verified: "bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10",
    Pending: "bg-amber-50 text-amber-600 dark:bg-amber-500/10",
    "Action Required": "bg-red-50 text-red-600 dark:bg-red-500/10 animate-pulse",
    Expiring: "bg-orange-50 text-orange-600 dark:bg-orange-500/10",
    Signed: "bg-blue-50 text-blue-600 dark:bg-blue-500/10"
  };
  return <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${styles[status]}`}>{status}</span>;
}